# mto VERSION completions for bash, generated by `mto completions bash`; do not edit.
# Works with bash 3.2 and later, with or without the bash-completion package.

# Whether flag $1 is followed by its value.
_mto_takes_value() {
  case "$1" in
    --emit|--stdin-filepath|--config|--config-path|--edition|--print-config|--style-edition|--color|--keep|--dir|--older-than) return 0 ;;
  esac
  return 1
}

# Adds each word after $1 that, after $1, starts the word being completed.
_mto_words() {
  local before="$1" word
  shift
  for word in "$@"; do
    case "$before$word" in
      "$_mto_cur"*) COMPREPLY+=("$before$word ") ;;
    esac
  done
}

# Adds the paths starting with $2, after $1: folders, and Rust files, or every file
# when no Rust file matches; only folders when $3 is dirs.
_mto_paths() {
  local before="$1" path IFS='
'
  local dirs=() files=()
  dirs=($(compgen -d -- "$2"))
  if [ "$3" != dirs ]; then
    files=($(compgen -f -X '!*.rs' -- "$2"))
    if [ ${#files[@]} -eq 0 ]; then
      files=($(compgen -f -- "$2"))
    fi
  fi
  if [ ${#dirs[@]} -gt 0 ]; then
    for path in "${dirs[@]}"; do
      COMPREPLY+=("$before$path/")
    done
  fi
  if [ ${#files[@]} -gt 0 ]; then
    for path in "${files[@]}"; do
      [ -d "$path" ] || COMPREPLY+=("$before$path ")
    done
  fi
}

# --config's pairs, after $1: the settings, then after `=` the setting's values.
_mto_settings() {
  local head="" last="$2" key
  case "$2" in
    *,*) head="${2%,*},"; last="${2##*,}" ;;
  esac
  case "$last" in
    *=*)
      key="${last%%=*}"
      _mto_words "$1$head$key=" $(_mto_setting_values "$key")
      ;;
    *)
      for key in array_width attr_fn_like_width binop_separator blank_lines_lower_bound \
        blank_lines_upper_bound brace_style chain_width color \
        combine_control_expr comment_width condense_wildcard_suffixes \
        control_brace_style disable_all_formatting \
        doc_comment_code_block_small_heuristics doc_comment_code_block_width \
        edition emit_mode empty_item_single_line enum_discrim_align_threshold \
        error_on_line_overflow error_on_unformatted \
        float_literal_trailing_zero fn_call_width fn_params_layout \
        fn_single_line force_explicit_abi force_multiline_blocks \
        format_code_in_doc_comments format_generated_files format_macro_bodies \
        format_macro_matchers format_strings \
        generated_marker_line_search_limit group_imports hard_tabs \
        hex_literal_case ignore imports_granularity imports_indent \
        imports_layout indent_style inline_attribute_width make_backup \
        match_arm_blocks match_arm_indent match_arm_leading_pipes \
        match_block_trailing_comma max_width merge_derives newline_style \
        normalize_comments normalize_doc_attributes overflow_delimited_expr \
        remove_nested_parens reorder_impl_items reorder_imports \
        reorder_modules required_version short_array_element_width_threshold \
        show_parse_errors single_line_if_else_max_width \
        single_line_let_else_max_width skip_children skip_macro_invocations \
        space_after_colon space_before_colon spaces_around_ranges \
        struct_field_align_threshold struct_lit_single_line struct_lit_width \
        struct_variant_width style_edition tab_spaces trailing_comma \
        trailing_semicolon type_punctuation_density unstable_features \
        use_field_init_shorthand use_small_heuristics use_try_shorthand \
        version where_single_line wrap_comments blank_lines_between_blocks \
        generated_markers group_impls ignore_dirs impl_method_order \
        import_grouping import_sort layout format layout_generated_files \
        name_sort sort_alphabetically sort_imports test_module \
        trait_impl_order trait_impl_sort type_order visibility_order; do
        case "$1$head$key=" in
          "$_mto_cur"*) COMPREPLY+=("$1$head$key=") ;;
        esac
      done
      ;;
  esac
}

# The values setting $1 takes, when they are a fixed set.
_mto_setting_values() {
  case "$1" in
    binop_separator) echo Front Back ;;
    brace_style) echo AlwaysNextLine PreferSameLine SameLineWhere ;;
    color) echo Always Never Auto ;;
    combine_control_expr|condense_wildcard_suffixes|disable_all_formatting|empty_item_single_line|error_on_line_overflow|error_on_unformatted|fn_single_line|force_explicit_abi|force_multiline_blocks|format_code_in_doc_comments|format_generated_files|format_macro_bodies|format_macro_matchers|format_strings|hard_tabs|make_backup|match_arm_blocks|match_arm_indent|match_block_trailing_comma|merge_derives|normalize_comments|normalize_doc_attributes|overflow_delimited_expr|remove_nested_parens|reorder_impl_items|reorder_imports|reorder_modules|show_parse_errors|skip_children|space_after_colon|space_before_colon|spaces_around_ranges|struct_lit_single_line|trailing_semicolon|unstable_features|use_field_init_shorthand|use_try_shorthand|where_single_line|wrap_comments|group_impls|import_grouping|layout|format|layout_generated_files|sort_alphabetically|sort_imports) echo true false ;;
    control_brace_style) echo AlwaysSameLine ClosingNextLine AlwaysNextLine ;;
    doc_comment_code_block_small_heuristics) echo Inherit Off Max Default ;;
    edition) echo 2015 2018 2021 2024 ;;
    emit_mode) echo Files Stdout Coverage Checkstyle Json ModifiedLines Diff ;;
    float_literal_trailing_zero) echo Preserve Always IfNoPostfix Never ;;
    fn_params_layout) echo Compressed Tall Vertical ;;
    group_imports) echo Preserve StdExternalCrate One ;;
    hex_literal_case) echo Preserve Upper Lower ;;
    imports_granularity) echo Preserve Crate Module Item One ;;
    imports_indent|indent_style) echo Visual Block ;;
    imports_layout) echo Vertical Horizontal HorizontalVertical Mixed ;;
    match_arm_leading_pipes) echo Always Never Preserve ;;
    newline_style) echo Auto Windows Unix Native ;;
    style_edition) echo 2015 2018 2021 2024 2027 ;;
    trailing_comma) echo Always Never Vertical ;;
    type_punctuation_density) echo Compressed Wide ;;
    use_small_heuristics) echo Off Max Default ;;
    version) echo One Two ;;
    impl_method_order) echo written trait ;;
    import_sort) echo style_edition 2015 2024 ;;
    name_sort) echo version bytes case_insensitive ;;
    test_module) echo last in_place ;;
    trait_impl_sort) echo name original ;;
  esac
}

# Completes the value of flag $1, after $2; $3 is the value so far.
_mto_value() {
  case "$1" in
    --emit) _mto_words "$2" files stdout json ;;
    --stdin-filepath) _mto_paths "$2" "$3" ;;
    --config) _mto_settings "$2" "$3" ;;
    --config-path) _mto_paths "$2" "$3" ;;
    --edition) _mto_words "$2" 2015 2018 2021 2024 ;;
    --print-config) _mto_words "$2" default minimal current ;;
    --style-edition) _mto_words "$2" 2015 2018 2021 2024 2027 ;;
    --color) _mto_words "$2" always never auto ;;
    --dir) _mto_paths "$2" "$3" dirs ;;
  esac
}

# The flags that may follow command $1 and subcommand $2 (either may be empty).
_mto_flags() {
  case "$1 $2" in
    " ") _mto_words "" --check -d --dry-run --emit -l --files-with-diff --follow-links -R --recursive --skip-children --stdin-filepath --config --config-path --edition --print-config --style-edition --unstable-features --allow-dirty --unguarded --no-history --color --dbg -q --quiet -v --verbose -h --help --man -V --version ;;
    "init ") _mto_words "" -h --help ;;
    "config ") _mto_words "" -h --help ;;
    "config path") _mto_words "" -h --help --config --config-path --edition --style-edition ;;
    "config print") _mto_words "" -h --help --current --default --minimal --user --config --config-path --edition --style-edition ;;
    "config options") _mto_words "" -h --help --toml ;;
    "history ") _mto_words "" -h --help --all ;;
    "history show") _mto_words "" -h --help ;;
    "history prune") _mto_words "" -h --help --keep --older-than ;;
    "restore ") _mto_words "" -h --help --force ;;
    "doctor ") _mto_words "" -h --help ;;
    "doctor on") _mto_words "" -h --help ;;
    "doctor off") _mto_words "" -h --help ;;
    "doctor holds") _mto_words "" -h --help ;;
    "doctor release") _mto_words "" -h --help ;;
    "report ") _mto_words "" -h --help ;;
    "report show") _mto_words "" -h --help ;;
    "report save") _mto_words "" -h --help --with-file ;;
    "report send") _mto_words "" -h --help ;;
    "report prune") _mto_words "" -h --help ;;
    "debug ") _mto_words "" -h --help ;;
    "debug tokens") _mto_words "" -h --help --edition ;;
    "debug tree") _mto_words "" -h --help --edition ;;
    "debug layout") _mto_words "" -h --help --edition ;;
    "completions ") _mto_words "" -h --help ;;
    "completions install") _mto_words "" -h --help --dir -d --dry-run ;;
    "completions uninstall") _mto_words "" -h --help --dir -d --dry-run ;;
    "completions status") _mto_words "" -h --help ;;
  esac
}

# The subcommands of command $1.
_mto_subcommands() {
  case "$1" in
    config) _mto_words "" path print options ;;
    history) _mto_words "" show prune ;;
    doctor) _mto_words "" on off holds release ;;
    report) _mto_words "" show save send prune ;;
    debug) _mto_words "" tokens tree layout ;;
    completions) _mto_words "" install uninstall status ;;
  esac
}

# Completes an argument of command $1 and subcommand $2; $3 is the argument so far.
_mto_operand() {
  case "$1 $2" in
    "init "|"config path"|"config print") _mto_paths "" "$3" dirs ;;
    "restore "|"report save"|"debug tokens"|"debug tree"|"debug layout") _mto_paths "" "$3" ;;
    "completions "|"completions install"|"completions uninstall"|"completions status") _mto_words "" bash zsh fish powershell ;;
  esac
}

_mto() {
  local _mto_cur words=() w i n=0 keep="" command="" sub="" operands=0 expect=""
  COMPREPLY=()
  # bash splits `--emit=json` and `max_width=80` at `=`: put them back together.
  for ((i = 1; i <= COMP_CWORD; i++)); do
    w="${COMP_WORDS[i]}"
    if [ $n -gt 0 ] && { [ "$w" = "=" ] || [ "${words[n-1]%=}" != "${words[n-1]}" ]; }; then
      words[n-1]="${words[n-1]}$w"
    else
      words[n]="$w"
      n=$((n + 1))
    fi
  done
  _mto_cur="${words[n-1]}"
  # Readline replaces only what follows the word's last `=`.
  case "$COMP_WORDBREAKS" in
    *=*) case "$_mto_cur" in *=*) keep="${_mto_cur%=*}=" ;; esac ;;
  esac
  # The command and subcommand given so far, and how many arguments followed.
  for ((i = 0; i < n - 1; i++)); do
    w="${words[i]}"
    if [ -n "$expect" ]; then
      expect=""
      continue
    fi
    case "$w" in
      --) return 0 ;;
      --*=*) ;;
      -?*) _mto_takes_value "$w" && expect="$w" ;;
      *)
        if [ $operands -eq 0 ] && [ -z "$command" ] && _mto_is_command "$w"; then
          command="$w"
        elif [ $operands -eq 0 ] && [ -n "$command" ] && [ -z "$sub" ] \
          && _mto_is_subcommand "$command" "$w"; then
          sub="$w"
        else
          operands=$((operands + 1))
        fi
        ;;
    esac
  done
  if [ -n "$expect" ]; then
    _mto_value "$expect" "" "$_mto_cur"
  else
    case "$_mto_cur" in
      --*=*) _mto_value "${_mto_cur%%=*}" "${_mto_cur%%=*}=" "${_mto_cur#*=}" ;;
      -*) _mto_flags "$command" "$sub" ;;
      *)
        if [ -z "$command" ]; then
          [ $operands -eq 0 ] && _mto_words "" init config history restore doctor report debug completions
          _mto_paths "" "$_mto_cur"
        else
          if [ $operands -eq 0 ] && [ -z "$sub" ]; then
            _mto_subcommands "$command"
          fi
          _mto_operand "$command" "$sub" "$_mto_cur"
        fi
        ;;
    esac
  fi
  if [ -n "$keep" ]; then
    for ((i = 0; i < ${#COMPREPLY[@]}; i++)); do
      COMPREPLY[i]="${COMPREPLY[i]#"$keep"}"
    done
  fi
  return 0
}

# Whether $1 is one of mto's commands.
_mto_is_command() {
  case "$1" in
    init|config|history|restore|doctor|report|debug|completions) return 0 ;;
  esac
  return 1
}

# Whether $2 is a subcommand of command $1.
_mto_is_subcommand() {
  case "$1 $2" in
    "config path"|"config print"|"config options"|"history show"|"history prune"|"doctor on"|"doctor off"|"doctor holds"|"doctor release"|"report show"|"report save"|"report send"|"report prune"|"debug tokens"|"debug tree"|"debug layout"|"completions install"|"completions uninstall"|"completions status") return 0 ;;
  esac
  return 1
}

complete -o nospace -F _mto mto
